#!/usr/bin/env bash
# DREAM · stage 1 assets (Seedream 5.0 Pro 2K). Handles = file names: @char_pilot @prop_dream @loc_hangar @loc_coast @loc_pad
set -euo pipefail
cd "$(dirname "$0")/../.."
J="python3 tools/jm.py film02/jimeng-state.json"

$J img char_pilot --title "@char_pilot · 驾驶员三联定妆照" --ref N3 --prompt "Create a photorealistic three-panel character sheet, 16:9, three equal panels side by side with thin divider lines. The same man in every panel. An East Asian man around 30, short black hair, light natural stubble, calm focused dark-brown eyes like the reference eye, real skin with visible pores, natural tonal variation and slight asymmetry. No airbrushing, no beauty retouching, do not slim, symmetrize or beautify. He wears a matte black one-piece flight suit with a high collar and a front zip, black leather gloves and black boots; he holds a matte black full-face helmet with a dark smoked visor under his left arm. LEFT: frontal head-and-shoulders portrait, head square to camera, eyes to the lens, neutral calm expression, helmet not on. CENTRE: front full-body view cropped at the base of the neck, standing upright, helmet under the left arm, both gloved hands visible. RIGHT: back full-body view at the same neck-down crop and scale. Both body panels share one ground line with the boots fully visible. The face appears only in the portrait. Seamless neutral mid-grey studio background, broad soft even light, neutral white balance, gentle grounded shadows, matte fabric texture. No text, logos, patches or labels, no film filter, no illustration or CGI look."

$J img prop_dream --title "@prop_dream · Dream 三视图" --ref K1 --ref G-v2-side --ref G-v4-top --ref G-v1-front34 --prompt "Create a photorealistic three-panel product sheet, 16:9, three equal panels side by side with thin divider lines, the same aircraft in every panel, exactly as in the references: a CoolFly Dream single-seat electric multirotor with an orange glossy front fairing carrying two white vertical racing stripes and the number 05, a dark-grey tubular steel roll cage with an arched roof, a white bucket seat with harness, four carbon-fibre arms in an X layout, a coaxial pair of black motors at the tip of each arm (one above, one below) with two-blade carbon propellers, eight propellers in total, and an open perforated steel floor. Propellers still. LEFT: front three-quarter view from slightly above. CENTRE: exact side view, nose to the right. RIGHT: exact top-down view, nose up. Identical scale in all panels. Seamless neutral light-grey studio background, broad soft even light, gentle grounded shadows, crisp real materials: carbon weave, clear-coated paint, matte steel. Never redesign the aircraft; no extra or missing arms, motors or propellers; no added logos, labels or text."

$J img loc_hangar --title "@loc_hangar · 机库" --prompt "Create a photorealistic cinematic location still, 16:9: an empty large aircraft hangar at night, seen as a wide three-quarter view from floor level near the left wall. Polished concrete floor with a thin film of standing water that mirrors the lights. Six rows of linear LED ceiling fixtures run from a tall rolling door at the far end toward the camera; all are switched on. A painted square landing pad marks the centre of the floor and is empty. A steel tool cart stands against the left wall in the foreground; a small side door with a lit window is at screen right. The rolling door at the far end is half open, showing a pale blue dawn sky over the sea. Leave clear open floor around the pad for an aircraft to stand and lift off. Clean modern digital cinema look, cold white light, deep clean blacks, crisp detail. No people, aircraft, vehicles or readable text."

$J img loc_coast --title "@loc_coast · 海岸" --prompt "Create a photorealistic cinematic location still, 16:9: a dramatic rocky coastline in the early morning, seen from the air at about 40 metres, looking along the coast. Black basalt cliffs drop into deep blue-grey sea with white surf at their base. A tall dark sea stack stands offshore in the middle distance. A white lighthouse sits on the far headland. Soft silver overcast with a low sun breaking through near the horizon and catching the wave tops. Open air above the water in the foreground for an aircraft to fly through. Clean modern digital cinema look, deep clean blacks, natural saturated colour, crisp detail. No aircraft, boats, people or readable text."

$J img loc_pad --title "@loc_pad · 崖顶起降台 黄昏" --prompt "Create a photorealistic cinematic location still, 16:9: a flat circular concrete landing pad with a thin painted orange ring, set on a grassy cliff top high above the sea at dusk. Seen from low on the grass at the pad's edge, looking across the pad toward the sea. The sun sits just above the horizon behind the pad, warm golden light skimming the grass and the concrete, long soft shadows, the sea below glittering. A low dry-stone wall runs along the cliff edge at the right. Leave the pad completely empty with open space above it for an aircraft to land. Clean modern digital cinema look, rich warm colour, deep clean blacks, crisp detail. No aircraft, people, vehicles or readable text."
